+  // Independent-pixel shapes measured on M4 Pro. Pipeline and device limits
+  // are checked once. Other devices retain the original 8x8 launches.
+  if (device->supportsFamily(MTL::GPUFamilyApple9)) {
+    const MTL::Size limit = device->maxThreadsPerThreadgroup();
+    const auto select = [limit](MTL::ComputePipelineState* pipeline,
+                                MTL::Size preferred) {
+      return pipeline->threadExecutionWidth() == 32 &&
+             pipeline->maxTotalThreadsPerThreadgroup() >=
+               preferred.width * preferred.height &&
+             preferred.width <= limit.width && preferred.height <= limit.height
+        ? preferred : MTL::Size(8, 8, 1);
+    };
+    pipelines.convolution_transpose_threads = select(
+      pipelines.convolution_transpose.get(), MTL::Size(16, 16, 1));
+    pipelines.ultra_mask_threads = select(
+      pipelines.frequency_ultra_mask_convolve.get(), MTL::Size(16, 8, 1));
+    pipelines.subsample_threads = select(
+      pipelines.subsample.get(), MTL::Size(16, 8, 1));
+  }
   *out = std::move(pipelines);
   return Status::Ok();
